<?php require dirname(__DIR__).'/lib.php';if(!empty($_SESSION['apple_admin'])){header('Location: index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();if(empty(cfg()['admin_password_hash']))throw new RuntimeException('관리자 비밀번호 해시를 config.php에 설정하세요.');if(!preg_match('/^[0-9]{4}$/D', (string)($_POST['password']??'')) || !password_verify((string)($_POST['password']??''),cfg()['admin_password_hash'])){usleep(400000);throw new RuntimeException('비밀번호가 올바르지 않습니다.');}session_regenerate_id(true);$_SESSION['apple_admin']=true;header('Location: index.php');exit;}catch(Throwable $e){$error=$e->getMessage();}}layout_start('농장 관리자 로그인');?><div class="card" style="max-width:430px;margin:auto"><h1>🍎 농장 관리자</h1><?php if($error):?><p class="error"><?=h($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>관리자 비밀번호</label><input name="password" type="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" required autocomplete="current-password"><div class="actions"><button>로그인</button><a class="btn secondary" href="../index.php">주문 화면</a></div></form></div><?php layout_end();
